sysauto_script.script:
(function () {
    var VIZ_FIXES = {
        '3eb4e572c9ab4f668fd29fb5b9400b1b': { table: 'x_1295779_metpo_viz_column', viz_type: 'column_chart' },
        'f479524e87774b5cabe74100b75e5e70': { table: 'x_1295779_metpo_viz_line', viz_type: 'line_chart' },
        '5a643826417a422899c02309d635d971': { table: 'x_1295779_metpo_viz_pie', viz_type: 'pie_chart' },
        '1831007364ca43008d69a1dccd206c6b': { table: 'x_1295779_metpo_viz_boxplot', viz_type: 'box_plot' },
        '9c718bfa5aed49cfb6161c3c0930e48d': { table: 'x_1295779_metpo_viz_scatter', viz_type: 'scatter_chart' }
    };

    for (var vizId in VIZ_FIXES) {
        var fix = VIZ_FIXES[vizId];
        var vizGr = new GlideRecord(fix.table);
        if (vizGr.get(vizId)) {
            vizGr.setValue('viz_type', fix.viz_type);
            vizGr.setValue('chart_title', '');
            vizGr.update();
            gs.info('PerformanceDashboardFix: Updated viz "' + vizGr.getValue('name') + '" -> ' + fix.viz_type);
        } else {
            gs.warn('PerformanceDashboardFix: Viz not found: ' + vizId);
        }
    }

    var SOURCE_FIXES = [
        {
            sys_id: 'd6248c70890c4c8297e670f064245ee8',
            name: 'Incident Trend (30 Days)',
            updates: { source_type: 'table_aggregate', src_limit: '30' },
            clear: ['src_x_field', 'src_y_field', 'src_lookback_days']
        },
        {
            sys_id: '48e6ab3564134f349560d26942949ecf',
            name: 'Resolution Time by Priority',
            updates: { source_type: 'table_aggregate', src_limit: '500' },
            clear: ['src_indicator', 'src_breakdown', 'src_elements']
        },
        {
            sys_id: '313d3aaf60ae4959ba98849f9eedc2b7',
            name: 'Response vs Resolution Correlation',
            updates: { source_type: 'table_aggregate', src_limit: '100' },
            clear: ['src_script_include', 'src_method', 'src_params', 'src_value_field']
        }
    ];

    for (var i = 0; i < SOURCE_FIXES.length; i++) {
        var srcFix = SOURCE_FIXES[i];
        var srcGr = new GlideRecord('x_1295779_metpo_source_config');
        if (srcGr.get(srcFix.sys_id)) {
            for (var field in srcFix.updates) {
                srcGr.setValue(field, srcFix.updates[field]);
            }
            for (var c = 0; c < srcFix.clear.length; c++) {
                srcGr.setValue(srcFix.clear[c], '');
            }
            srcGr.update();
            gs.info('PerformanceDashboardFix: Updated "' + srcFix.name + '" -> source_type=' + srcFix.updates.source_type);
        } else {
            gs.warn('PerformanceDashboardFix: Source config not found: ' + srcFix.sys_id);
        }
    }

    gs.info('PerformanceDashboardFix: All fixes applied.');
})();
